        <div className="absolute -top-40 -left-40 h-96 w-96 rounded-full bg-cyan-500/10 blur-[120px]" />
        <div className="absolute top-1/2 -right-40 h-96 w-96 rounded-full bg-blue-600/10 blur-[120px]" />
      </div>

      {/* Contenedor con control de desbordamiento estricto */}
      <main className="relative z-10 flex h-screen w-full flex-col overflow-hidden p-4 lg:p-6">
        <div className="flex-1 overflow-y-auto overflow-x-hidden rounded-3xl border border-white/10 bg-slate-900/40 p-4 shadow-2xl backdrop-blur-2xl lg:p-6">
